Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'REMPRODDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remProdDescricao1.FromString(&GridStateDynamicFilter.Value) If not &remProdDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterremProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterremProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &remProdDescricao = &remProdDescricao1 print printBlockFilterremProdDescricao EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'REMPRODDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remProdDescricao2.FromString(&GridStateDynamicFilter.Value) If not &remProdDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterremProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterremProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &remProdDescricao = &remProdDescricao2 print printBlockFilterremProdDescricao EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'REMPRODDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remProdDescricao3.FromString(&GridStateDynamicFilter.Value) If not &remProdDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterremProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterremProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &remProdDescricao = &remProdDescricao3 print printBlockFilterremProdDescricao EndIf EndCase EndIf EndIf EndIf If not (&TFremProdCodigo.IsEmpty() AND &TFremProdCodigo_To.IsEmpty()) print printBlockTFremProdCodigo &TFremProdCodigo_To_Description = format('%1 (%2)', "Código", "WWP_TSTo") print printBlockTFremProdCodigo_To EndIf If not &TFremProdDescricao_Sel.IsEmpty() print printBlockTFremProdDescricao_Sel Else If not &TFremProdDescricao.IsEmpty() print printBlockTFremProdDescricao EndIf EndIf If not &TFremProdUnPeso_Sel.IsEmpty() print printBlockTFremProdUnPeso_Sel Else If not &TFremProdUnPeso.IsEmpty() print printBlockTFremProdUnPeso EndIf EndIf If not &TFremProdAreEnsCodigo_Sel.IsEmpty() print printBlockTFremProdAreEnsCodigo_Sel Else If not &TFremProdAreEnsCodigo.IsEmpty() print printBlockTFremProdAreEnsCodigo EndIf EndIf If not &TFremProdAreEnsSequencial_Sel.IsEmpty() print printBlockTFremProdAreEnsSequencial_Sel Else If not &TFremProdAreEnsSequencial.IsEmpty() print printBlockTFremProdAreEnsSequencial EndIf EndIf &TFremProdAreEnsTurno_Sels.FromJson(&TFremProdAreEnsTurno_SelsJson) If not &TFremProdAreEnsTurno_Sels.Count = 0 &i = 1 For &TFremProdAreEnsTurno_Sel in &TFremProdAreEnsTurno_Sels If &i = 1 &TFremProdAreEnsTurno_SelDscs = '' Else &TFremProdAreEnsTurno_SelDscs += ', ' EndIf &FilterTFremProdAreEnsTurno_SelValueDescription = '' Do Case Case &TFremProdAreEnsTurno_Sel = 1 &FilterTFremProdAreEnsTurno_SelValueDescription = "Matutino"
Case &TFremProdAreEnsTurno_Sel = 2 &FilterTFremProdAreEnsTurno_SelValueDescription = "Vespertino"
Case &TFremProdAreEnsTurno_Sel = 3 &FilterTFremProdAreEnsTurno_SelValueDescription = "Noturno"
Case &TFremProdAreEnsTurno_Sel = 4 &FilterTFremProdAreEnsTurno_SelValueDescription = "Integral"
Case &TFremProdAreEnsTurno_Sel = 5 &FilterTFremProdAreEnsTurno_SelValueDescription = "Interm. Matutino"
Case &TFremProdAreEnsTurno_Sel = 6 &FilterTFremProdAreEnsTurno_SelValueDescription = "Interm. Vespertino"
EndCase
&TFremProdAreEnsTurno_SelDscs += &FilterTFremProdAreEnsTurno_SelValueDescription &i += 1 EndFor print printBlockTFremProdAreEnsTurno_Sel EndIf If not (&TFremProdQtde.IsEmpty() AND &TFremProdQtde_To.IsEmpty()) print printBlockTFremProdQtde &TFremProdQtde_To_Description = format('%1 (%2)', "Qtde", "WWP_TSTo") print printBlockTFremProdQtde_To EndIf If not (&TFremProdPerCapta.IsEmpty() AND &TFremProdPerCapta_To.IsEmpty()) print printBlockTFremProdPerCapta &TFremProdPerCapta_To_Description = format('%1 (%2)', "Capta", "WWP_TSTo") print printBlockTFremProdPerCapta_To EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsremessaproduto order prefCodigo remCodigo remProdDescricao when &OrderedBy = 1 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdDescricao) when &OrderedBy = 1 AND &OrderedDsc = True order prefCodigo remCodigo remProdCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order prefCodigo remCodigo remProdUnPeso when &OrderedBy = 3 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdUnPeso) when &OrderedBy = 3 AND &OrderedDsc = True order prefCodigo remCodigo remProdAreEnsCodigo when &OrderedBy = 4 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdAreEnsCodigo) when &OrderedBy = 4 AND &OrderedDsc = True order prefCodigo remCodigo remProdAreEnsSequencial when &OrderedBy = 5 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdAreEnsSequencial) when &OrderedBy = 5 AND &OrderedDsc = True order prefCodigo remCodigo remProdAreEnsTurno when &OrderedBy = 6 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdAreEnsTurno) when &OrderedBy = 6 AND &OrderedDsc = True order prefCodigo remCodigo remProdQtde when &OrderedBy = 7 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdQtde) when &OrderedBy = 7 AND &OrderedDsc = True order prefCodigo remCodigo remProdPerCapta when &OrderedBy = 8 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdPerCapta) when &OrderedBy = 8 AND &OrderedDsc = True
using trnsremessaprodutoWWDS(&prefCodigo, &remCodigo, &DynamicFiltersSelector1, &DynamicFiltersOperator1, &remProdDescricao1, &DynamicFiltersEnabled2 , &DynamicFiltersSelector2, &DynamicFiltersOperator2, &remProdDescricao2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &remProdDescricao3, &TFremProdCodigo, &TFremProdCodigo_To, &TFremProdDescricao, &TFremProdDescricao_Sel, &TFremProdUnPeso , &TFremProdUnPeso_Sel, &TFremProdAreEnsCodigo, &TFremProdAreEnsCodigo_Sel, &TFremProdAreEnsSequencial, &TFremProdAreEnsSequencial_Sel, &TFremProdAreEnsTurno_Sels , &TFremProdQtde, &TFremProdQtde_To, &TFremProdPerCapta, &TFremProdPerCapta_To) Where prefCodigo = &prefCodigo &remProdAreEnsTurnoDescription = '' Do Case Case remProdAreEnsTurno = 1 &remProdAreEnsTurnoDescription = "Matutino"
Case remProdAreEnsTurno = 2 &remProdAreEnsTurnoDescription = "Vespertino"
Case remProdAreEnsTurno = 3 &remProdAreEnsTurnoDescription = "Noturno"
Case remProdAreEnsTurno = 4 &remProdAreEnsTurnoDescription = "Integral"
Case remProdAreEnsTurno = 5 &remProdAreEnsTurnoDescription = "Interm. Matutino"
Case remProdAreEnsTurno = 6 &remProdAreEnsTurnoDescription = "Interm. Vespertino"
EndCase
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsremessaprodutoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsremessaprodutoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsremessaprodutoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFREMPRODCODIGO" &TFremProdCodigo.FromString(&GridStateFilterValue.Value) &TFremProdCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMPRODDESCRICAO" &TFremProdDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODDESCRICAO_SEL" &TFremProdDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODUNPESO" &TFremProdUnPeso.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODUNPESO_SEL" &TFremProdUnPeso_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSCODIGO" &TFremProdAreEnsCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSCODIGO_SEL" &TFremProdAreEnsCodigo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSSEQUENCIAL" &TFremProdAreEnsSequencial.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSSEQUENCIAL_SEL" &TFremProdAreEnsSequencial_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSTURNO_SEL" &TFremProdAreEnsTurno_SelsJson = &GridStateFilterValue.Value &TFremProdAreEnsTurno_Sels.FromJson(&TFremProdAreEnsTurno_SelsJson) Case &GridStateFilterValue.Name = !"TFREMPRODQTDE" &TFremProdQtde.FromString(&GridStateFilterValue.Value) &TFremProdQtde_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMPRODPERCAPTA" &TFremProdPerCapta.FromString(&GridStateFilterValue.Value) &TFremProdPerCapta_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"PARM_&PREFCODIGO" &prefCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&REMCODIGO" &remCodigo.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
